//! Generated images fed back as input on Gemini: see `common/image_inputs.rs`.

use rig::completion::{CompletionRequest, ToolDefinition};
use rig::message::Message;
use rig::providers::gemini;

use super::super::request_witness_support::{
    NamedCase, model_result, with_gemini_request_witness_cassette,
};
use crate::image_inputs;

/// A Gemini 3 model reads the generated bytes as a multimodal function
/// response (2.5 rejects images in function responses).
///
/// Exact named mismatch witness (mec-rig-132-dispositions-1 item 5,
/// mec-rig-schema-route-1 item 1(b)): the recording is unchanged. Interaction
/// 0, the image generation, replays exactly and still yields image bytes
/// (`image_inputs::generate`). Interaction 1 is the first turn of
/// `image_inputs::as_tool_result`, rebuilt here from its private inputs (the
/// render_swatch declaration, the prompt naming its question, 1024 output
/// tokens, no parameters) because that driver panics on the refusal; its only
/// request difference is that declaration 0's recorded
/// `parametersJsonSchema` is sent as `parameters`, and replay refuses it.
/// Named losses: the model calling render_swatch, the second request carrying
/// the generated bytes as an image tool result, and the reply naming red.
/// The recording's own byte-equality rule
/// (`image_inputs::assert_recorded`, tool-result slot) still runs on the
/// fixture.
#[tokio::test]
async fn generated_image_as_tool_result() -> anyhow::Result<()> {
    const SCENARIO: &str = "image_input_matrix/generated_image_as_tool_result";
    with_gemini_request_witness_cassette(
        "image_input_matrix/generated_image_as_tool_result",
        NamedCase::GeneratedImageToolResult,
        |client, _clock| async move {
            image_inputs::generate(
                &client.image_generation(gemini::GEMINI_2_5_FLASH_IMAGE),
                None,
                None,
            )
            .await;
            let tool = ToolDefinition {
                name: rig_core::message::ToolName::new("render_swatch").expect("tool name"),
                description: "Render the swatch image the user asks about.".to_owned(),
                parameters: serde_json::json!({ "type": "object", "properties": {}, "required": [] }),
            };
            let prompt = Message::user(
                "Call render_swatch, then answer: What single colour fills this image? Answer \
                 with one lowercase word.",
            );
            let mut request = CompletionRequest::from(vec![prompt]);
            request.tools = vec![tool];
            request.max_tokens = Some(1024);
            Ok(model_result(
                client
                    .completion(gemini::completion::GEMINI_3_FLASH_PREVIEW)
                    .call(request)
                    .await,
            ))
        },
    )
    .await?;
    image_inputs::assert_recorded("gemini", SCENARIO, image_inputs::Slot::ToolResult);
    Ok(())
}
